// Lightweight shape tests — no real API calls needed
import { generateResponse } from './llmClient';

test('generateResponse is an async generator function', () => {
  // An async generator function has a constructor name of 'AsyncGeneratorFunction'
  const fn = generateResponse as unknown as Function;
  expect(fn.constructor.name).toBe('AsyncGeneratorFunction');
});

test('generateResponse returns an object with Symbol.asyncIterator', () => {
  // Calling an async generator returns an AsyncGenerator object
  // We check the shape without actually calling the Anthropic API
  const iter = generateResponse('system', 'hello');
  expect(typeof (iter as any)[Symbol.asyncIterator]).toBe('function');
  // Clean up: we won't iterate it (no real API key in tests)
  if (typeof (iter as any).return === 'function') {
    (iter as any).return();
  }
});

import Anthropic from '@anthropic-ai/sdk';

const client = new Anthropic();

/**
 * Stream a response from Claude, yielding each text delta as it arrives.
 *
 * Usage:
 *   for await (const chunk of generateResponse(system, user)) {
 *     process.stdout.write(chunk);
 *   }
 *
 * @param systemPrompt  Standing instructions for the model
 * @param userMessage   The user's input
 * @yields             Text delta strings from the model stream
 */
export async function* generateResponse(
  systemPrompt: string,
  userMessage: string,
): AsyncGenerator<string> {
  const stream = client.messages.stream({
    model: 'claude-3-5-haiku-20241022',
    max_tokens: 1024,
    system: systemPrompt,
    messages: [{ role: 'user', content: userMessage }],
  });

  // The SDK's stream emits 'text' events for each delta.
  // Iterating with for-await gives us each MessageStreamEvent;
  // we filter for content_block_delta events carrying text deltas.
  for await (const event of stream) {
    if (
      event.type === 'content_block_delta' &&
      event.delta.type === 'text_delta'
    ) {
      yield event.delta.text;
    }
  }
}
